//! Generated typed builtin registry and function display catalog.
//! Ladybug-derived rows remain in `catalog_rows.tsv`; Koko-only overloads come from `builtins.toml`.

use crate::AggOp;
use koko_common::{IntKind, LogicalType};
use std::cmp::Ordering;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum FunctionCatalogKind {
    Scalar,
    Rewrite,
    Aggregate,
    Table,
    StandaloneTable,
    Copy,
}

impl FunctionCatalogKind {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Scalar => "SCALAR FUNCTION",
            Self::Rewrite => "REWRITE FUNCTION",
            Self::Aggregate => "AGGREGATE FUNCTION",
            Self::Table => "TABLE FUNCTION",
            Self::StandaloneTable => "STANDALONE TABLE FUNCTION",
            Self::Copy => "COPY FUNCTION",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct FunctionCatalogEntry {
    pub name: &'static str,
    pub kind: FunctionCatalogKind,
    pub signature: &'static str,
}

