#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BuiltinFunction {
    Scalar(BuiltinScalar),
    Aggregate(AggOp),
    CatalogOnly,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum CatalogTypeId {
    Any,
    Bool,
    Int8,
    Int16,
    Int32,
    Int64,
    Int128,
    UInt8,
    UInt16,
    UInt32,
    UInt64,
    UInt128,
    Serial,
    Decimal,
    Double,
    Float,
    String,
    Date,
    Timestamp,
    TimestampNs,
    TimestampMs,
    TimestampSec,
    TimestampTz,
    Interval,
    Uuid,
    Blob,
    List,
    Array,
    Struct,
    Map,
    Union,
    Node,
    Rel,
    RecursiveRel,
    InternalId,
    Json,
}

impl CatalogTypeId {
    pub fn of(actual: &LogicalType) -> Self {
        match actual {
            LogicalType::Any => Self::Any,
            LogicalType::Bool => Self::Bool,
            LogicalType::Int(IntKind::I8) => Self::Int8,
            LogicalType::Int(IntKind::I16) => Self::Int16,
            LogicalType::Int(IntKind::I32) => Self::Int32,
            LogicalType::Int(IntKind::I64) => Self::Int64,
            LogicalType::Int(IntKind::I128) => Self::Int128,
            LogicalType::Int(IntKind::U8) => Self::UInt8,
            LogicalType::Int(IntKind::U16) => Self::UInt16,
            LogicalType::Int(IntKind::U32) => Self::UInt32,
            LogicalType::Int(IntKind::U64) => Self::UInt64,
            LogicalType::UInt128 => Self::UInt128,
            LogicalType::Serial => Self::Serial,
            LogicalType::Decimal(_, _) => Self::Decimal,
            LogicalType::Double => Self::Double,
            LogicalType::Float => Self::Float,
            LogicalType::String => Self::String,
            LogicalType::Date => Self::Date,
            LogicalType::Timestamp => Self::Timestamp,
            LogicalType::TimestampNs => Self::TimestampNs,
            LogicalType::TimestampMs => Self::TimestampMs,
            LogicalType::TimestampSec => Self::TimestampSec,
            LogicalType::TimestampTz => Self::TimestampTz,
            LogicalType::Interval => Self::Interval,
            LogicalType::Uuid => Self::Uuid,
            LogicalType::Blob => Self::Blob,
            LogicalType::List(_) => Self::List,
            LogicalType::Array(_, _) => Self::Array,
            LogicalType::Struct(_) => Self::Struct,
            LogicalType::Map(_, _) => Self::Map,
            LogicalType::Union(_) => Self::Union,
            LogicalType::Node(_) => Self::Node,
            LogicalType::Rel(_) => Self::Rel,
            LogicalType::RecursiveRel => Self::RecursiveRel,
            LogicalType::InternalId => Self::InternalId,
            LogicalType::Json => Self::Json,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum KokoOverloadFamily {
    Numeric,
}

#[derive(Debug, Clone, Copy)]
pub struct KokoOverloadDescriptor {
    pub family: KokoOverloadFamily,
    pub min_arity: usize,
    pub display_signature: &'static str,
}

#[derive(Debug, Clone, Copy)]
pub struct OverloadDescriptor {
    pub params: &'static [CatalogTypeId],
    pub result: Option<CatalogTypeId>,
    pub distinct: bool,
    pub display_signature: &'static str,
}

#[derive(Debug, Clone, Copy)]
pub struct BuiltinDescriptor {
    pub called_name: &'static str,
    pub function: BuiltinFunction,
    pub catalog_kind: FunctionCatalogKind,
    pub overloads: &'static [OverloadDescriptor],
    pub koko_overloads: &'static [KokoOverloadDescriptor],
    pub string_coerce: &'static [usize],
    pub variable_arity: bool,
    pub bindable: bool,
}

