fn ascii_fold(byte: u8) -> u8 {
    if byte.is_ascii_uppercase() {
        byte + (b'a' - b'A')
    } else {
        byte
    }
}

fn ascii_case_cmp(left: &str, right: &str) -> Ordering {
    let mut left = left.bytes().map(ascii_fold);
    let mut right = right.bytes().map(ascii_fold);
    loop {
        match (left.next(), right.next()) {
            (Some(a), Some(b)) if a != b => return a.cmp(&b),
            (Some(_), Some(_)) => {}
            (None, None) => return Ordering::Equal,
            (None, Some(_)) => return Ordering::Less,
            (Some(_), None) => return Ordering::Greater,
        }
    }
}

pub fn resolve_builtin(called_name: &str) -> Option<&'static BuiltinDescriptor> {
    BUILTIN_DESCRIPTORS
        .binary_search_by(|descriptor| ascii_case_cmp(descriptor.called_name, called_name))
        .ok()
        .map(|index| &BUILTIN_DESCRIPTORS[index])
}

pub fn resolve_builtin_scalar(called_name: &str) -> Option<BuiltinScalar> {
    let descriptor = resolve_builtin(called_name)?;
    if !descriptor.bindable {
        return None;
    }
    match descriptor.function {
        BuiltinFunction::Scalar(function) => Some(function),
        BuiltinFunction::Aggregate(_) | BuiltinFunction::CatalogOnly => None,
    }
}

